import time
class DB:
    def __init__(self):
        self.kv = {}
        self.expire = {}
        self.lazy_deleted = 0
    def set(self, k, v, ttl):
        self.kv[k] = v
        self.expire[k] = time.time() + ttl
    def get(self, k, now):
        if k in self.expire and self.expire[k] <= now:
            del self.kv[k]; del self.expire[k]; self.lazy_deleted += 1
            return None
        return self.kv.get(k)

db = DB()
db.set("a", "x", -1)  # 已过期
db.set("b", "y", 100)
now = time.time()
print("惰性删除(lazy expiration):")
print("  访问已过期 key 'a' ->", db.get("a", now))
print("  访问未过期 key 'b' ->", db.get("b", now))
print("  惰性删除次数:", db.lazy_deleted, "(过期键在访问时才删除, 不耗 CPU 直到被访问)")
